import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import {
  DecodeError,
  FrameType,
  parseControl,
  parseDeltaBatch,
  parseHeartbeat,
  parseSeriesRegistry,
  parseSnapshotHeader,
  readFrames,
  readUvarint,
  type DeltaBatch,
} from "../src/worker/decoder.ts";

/**
 * Fixtures generated by the Go encoder (cmd/genfixtures).
 *
 * The two implementations must agree byte for byte, and the only way to
 * know that is to test the TypeScript decoder against bytes the Go encoder
 * actually produced. Testing each side against its own idea of the format
 * would let both drift together.
 */
interface Fixture {
  name: string;
  bytes: number[];
  note: string;
}

const fixtures: Fixture[] = JSON.parse(
  readFileSync(fileURLToPath(new URL("./wire-fixtures.json", import.meta.url)), "utf8"),
);

function fixture(name: string): ArrayBuffer {
  const f = fixtures.find((x) => x.name === name);
  if (!f) throw new Error(`no fixture named ${name}`);
  return new Uint8Array(f.bytes).buffer;
}

// --- framing ---------------------------------------------------------------

describe("readFrames", () => {
  it("walks several frames coalesced into one message", () => {
    // Several frames routinely arrive in one WebSocket message; a reader
    // that assumes one frame per message silently drops the rest.
    const frames = readFrames(fixture("coalesced"));
    expect(frames.map((f) => f.type)).toEqual([
      FrameType.SeriesRegistry,
      FrameType.SnapshotHeader,
      FrameType.DeltaBatch,
    ]);
  });

  it("returns views rather than copies", () => {
    const buf = fixture("heartbeat");
    const [f] = readFrames(buf);
    expect(f.payload.buffer).toBe(buf);
  });

  it("rejects a truncated header", () => {
    expect(() => readFrames(new Uint8Array([1, 0, 0]).buffer)).toThrow(DecodeError);
  });

  it("rejects a frame claiming more bytes than remain", () => {
    const bad = new Uint8Array([0x03, 0x00, 0x00, 0x00, 0x64, 1, 2, 3]); // claims 100, has 3
    expect(() => readFrames(bad.buffer)).toThrow(/bytes but only/);
  });

  it("rejects an absurd length prefix without allocating", () => {
    // The classic length-prefix denial of service: bound on the claim,
    // not on the read.
    const bad = new Uint8Array([0x03, 0xff, 0xff, 0xff, 0xff]);
    expect(() => readFrames(bad.buffer)).toThrow(/over the maximum/);
  });

  it("handles an empty buffer", () => {
    expect(readFrames(new ArrayBuffer(0))).toEqual([]);
  });
});

// --- series registry -------------------------------------------------------

describe("parseSeriesRegistry", () => {
  it("decodes what Go encoded", () => {
    const [f] = readFrames(fixture("series_registry"));
    const defs = parseSeriesRegistry(f.payload);

    expect(defs).toHaveLength(2);
    expect(defs[0]).toEqual({
      id: 1,
      name: "node_cpu_percent",
      labels: { host: "a", dc: "eu" },
    });
    expect(defs[1]).toEqual({ id: 7, name: "up", labels: {} });
  });

  it("rejects a count that could not fit", () => {
    // A small hostile frame must not make the parser reserve a huge array.
    const payload = new DataView(new ArrayBuffer(8));
    payload.setUint32(0, 100_000, false);
    expect(() => parseSeriesRegistry(payload)).toThrow(/entries in/);
  });

  it("rejects a truncated payload", () => {
    expect(() => parseSeriesRegistry(new DataView(new ArrayBuffer(2)))).toThrow(DecodeError);
  });
});

// --- snapshot header -------------------------------------------------------

describe("parseSnapshotHeader", () => {
  it("decodes what Go encoded", () => {
    const [f] = readFrames(fixture("snapshot_header"));
    expect(parseSnapshotHeader(f.payload)).toEqual({
      watermarkTsMs: 1_700_000_123_456,
      seriesCount: 3,
    });
  });

  it("keeps millisecond precision past 2^32", () => {
    // A 64-bit timestamp read as two 32-bit halves, or through a float32,
    // loses milliseconds — and the watermark comparison is exact, so
    // losing one turns into a duplicated or dropped sample.
    const [f] = readFrames(fixture("snapshot_header"));
    const { watermarkTsMs } = parseSnapshotHeader(f.payload);
    expect(watermarkTsMs).toBeGreaterThan(2 ** 32);
    expect(Number.isSafeInteger(watermarkTsMs)).toBe(true);
  });

  it("rejects a short payload", () => {
    expect(() => parseSnapshotHeader(new DataView(new ArrayBuffer(11)))).toThrow(DecodeError);
  });
});

// --- delta batch -----------------------------------------------------------

describe("parseDeltaBatch", () => {
  it("decodes what Go encoded", () => {
    const frames = readFrames(fixture("delta_batch"));
    const batch = parseDeltaBatch(frames[0].payload);

    expect(batch.count).toBe(3);
    expect([...batch.seriesIds.slice(0, 3)]).toEqual([1, 2, 1]);
    expect(batch.timestamps[0]).toBe(1_700_000_000_000);
    expect(batch.timestamps[1]).toBe(1_700_000_000_200);
    expect(batch.timestamps[2]).toBe(1_700_000_100_000);
    expect(batch.values[0]).toBeCloseTo(1.5, 6);
    expect(batch.values[1]).toBeCloseTo(-3.25, 6);
    expect(batch.values[2]).toBe(0);
  });

  it("handles a multi-byte varint delta", () => {
    // The 100-second delta in the fixture needs three varint bytes. A
    // decoder that reads only one produces a timestamp 99.9 seconds early.
    const frames = readFrames(fixture("delta_batch"));
    const batch = parseDeltaBatch(frames[0].payload);
    expect(batch.timestamps[2] - batch.timestamps[0]).toBe(100_000);
  });

  it("returns struct-of-arrays, not objects", () => {
    // At 5 Hz across a thousand series, an array of point objects is five
    // thousand allocations per second for the GC to trace — the exact
    // cost the binary format exists to avoid.
    const frames = readFrames(fixture("delta_batch"));
    const batch = parseDeltaBatch(frames[0].payload);
    expect(batch.seriesIds).toBeInstanceOf(Uint32Array);
    expect(batch.timestamps).toBeInstanceOf(Float64Array);
    expect(batch.values).toBeInstanceOf(Float32Array);
  });

  it("reuses the destination arrays across calls", () => {
    const frames = readFrames(fixture("delta_batch"));
    const first = parseDeltaBatch(frames[0].payload);
    const second = parseDeltaBatch(frames[0].payload, first);

    expect(second).toBe(first);
    expect(second.seriesIds).toBe(first.seriesIds);
    expect(second.count).toBe(3);
  });

  it("grows the destination when a batch is larger", () => {
    const small: DeltaBatch = {
      seriesIds: new Uint32Array(1),
      timestamps: new Float64Array(1),
      values: new Float32Array(1),
      count: 0,
    };
    const frames = readFrames(fixture("delta_batch"));
    const grown = parseDeltaBatch(frames[0].payload, small);
    expect(grown.count).toBe(3);
    expect(grown.seriesIds.length).toBeGreaterThanOrEqual(3);
  });

  it("handles an empty batch", () => {
    const batch = parseDeltaBatch(new DataView(new ArrayBuffer(0)));
    expect(batch.count).toBe(0);
  });

  it("rejects a count that could not fit", () => {
    const payload = new DataView(new ArrayBuffer(12));
    payload.setUint32(8, 1_000_000, false);
    expect(() => parseDeltaBatch(payload)).toThrow(/points in/);
  });
});

// --- varint ----------------------------------------------------------------

describe("readUvarint", () => {
  it("matches Go's encoding/binary for known values", () => {
    const cases: Array<[bytes: number[], value: number]> = [
      [[0x00], 0],
      [[0x01], 1],
      [[0x7f], 127],
      [[0x80, 0x01], 128],
      [[0xff, 0x01], 255],
      [[0xa0, 0x8d, 0x06], 100_000],
      [[0xff, 0xff, 0xff, 0xff, 0x0f], 4_294_967_295],
    ];
    for (const [bytes, want] of cases) {
      const view = new DataView(new Uint8Array(bytes).buffer);
      expect(readUvarint(view, 0)[0], `bytes ${bytes}`).toBe(want);
    }
  });

  it("reports how many bytes it consumed", () => {
    const view = new DataView(new Uint8Array([0xa0, 0x8d, 0x06, 0xff]).buffer);
    expect(readUvarint(view, 0)).toEqual([100_000, 3]);
  });

  it("keeps precision past 2^31", () => {
    // JavaScript's bitwise operators coerce to int32, so a naive
    // implementation turns a large delta negative — and a negative
    // timestamp delta puts the point decades in the past.
    const view = new DataView(new Uint8Array([0x80, 0x80, 0x80, 0x80, 0x10]).buffer);
    const [value] = readUvarint(view, 0);
    expect(value).toBe(2 ** 32);
    expect(value).toBeGreaterThan(0);
  });

  it("rejects a truncated varint", () => {
    const view = new DataView(new Uint8Array([0x80, 0x80]).buffer);
    expect(() => readUvarint(view, 0)).toThrow(DecodeError);
  });

  it("rejects a varint longer than 10 bytes", () => {
    const view = new DataView(new Uint8Array(Array(12).fill(0xff)).buffer);
    expect(() => readUvarint(view, 0)).toThrow(/longer than 10/);
  });
});

// --- heartbeat and control -------------------------------------------------

describe("parseHeartbeat", () => {
  it("decodes what Go encoded", () => {
    const [f] = readFrames(fixture("heartbeat"));
    expect(parseHeartbeat(f.payload)).toBe(1_700_000_000_000);
  });

  it("rejects a short payload", () => {
    expect(() => parseHeartbeat(new DataView(new ArrayBuffer(7)))).toThrow(DecodeError);
  });
});

describe("parseControl", () => {
  it("round-trips JSON", () => {
    const json = JSON.stringify({ kind: 6, conflated: 42, dropped: 0, message: "slow" });
    const bytes = new TextEncoder().encode(json);
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    expect(parseControl(view)).toEqual({ kind: 6, conflated: 42, dropped: 0, message: "slow" });
  });

  it("decodes a control frame embedded in a larger buffer", () => {
    // The payload is a view into the message, not a standalone buffer; a
    // decoder that ignores byteOffset reads the frame header as JSON.
    const json = new TextEncoder().encode('{"kind":4}');
    const buf = new Uint8Array(10 + json.length);
    buf.set(json, 10);
    const view = new DataView(buf.buffer, 10, json.length);
    expect(parseControl(view)).toEqual({ kind: 4 });
  });
});
